PRAGMA journal_mode = WAL;
CREATE TABLE IF NOT EXISTS experiments (id TEXT PRIMARY KEY, scenario_id TEXT NOT NULL, scenario_version TEXT NOT NULL, comparison_mode TEXT NOT NULL, baseline_variant_id TEXT, repetitions INTEGER NOT NULL, inputs TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, started_at TEXT, finished_at TEXT);
CREATE TABLE IF NOT EXISTS variants (experiment_id TEXT NOT NULL, id TEXT NOT NULL, name TEXT NOT NULL, parameters TEXT NOT NULL, document TEXT NOT NULL, PRIMARY KEY (experiment_id, id));
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, experiment_id TEXT NOT NULL, variant_id TEXT NOT NULL, repetition INTEGER NOT NULL, state TEXT NOT NULL, measurement_validity TEXT NOT NULL, compose_project TEXT NOT NULL, resource_namespace TEXT NOT NULL, environment_snapshot TEXT, phase TEXT, started_at TEXT, measuring_at TEXT, finished_at TEXT, failure_kind TEXT, failure_reason TEXT, completeness TEXT, cleanup_status TEXT NOT NULL, summary TEXT, observer_health TEXT, phase_boundaries TEXT, UNIQUE (experiment_id, variant_id, repetition));
CREATE TABLE IF NOT EXISTS lifecycle_events (id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL, from_state TEXT NOT NULL, to_state TEXT NOT NULL, occurred_at TEXT NOT NULL, actor TEXT NOT NULL, reason TEXT NOT NULL, details TEXT);
CREATE TABLE IF NOT EXISTS artifacts (id TEXT PRIMARY KEY, run_id TEXT NOT NULL, kind TEXT NOT NULL, path TEXT NOT NULL, size_bytes INTEGER NOT NULL, format TEXT NOT NULL, source_metadata TEXT, created_at TEXT NOT NULL, retained INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS resources (run_id TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, ownership_labels TEXT NOT NULL, created_at TEXT NOT NULL, deleted_at TEXT, cleanup_result TEXT, PRIMARY KEY (run_id, resource_type, resource_id));
CREATE TABLE IF NOT EXISTS environments (environment_id TEXT PRIMARY KEY, run_id TEXT NOT NULL, state TEXT NOT NULL, document TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_keys (operation TEXT NOT NULL, idempotency_key TEXT NOT NULL, status_code INTEGER NOT NULL, response TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (operation, idempotency_key));
